#include "heat_source_heat_source.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void heat_source_heat_source_initialize(void);
void heat_source_heat_source_notify(microkit_channel channel);
void heat_source_heat_source_timeTriggered(void);

volatile sb_queue_Isolette_Data_Model_On_Off_1_t *heat_control_queue_1;
sb_queue_Isolette_Data_Model_On_Off_1_Recv_t heat_control_recv_queue;
volatile sb_queue_Isolette_Data_Model_On_Off_1_t *sv_heater_state_queue_1;

#define PORT_FROM_MON 0

volatile sb_event_counter_t *inj_clr_requests;
static sb_event_counter_t inj_clr_applied[1];

bool heat_control_is_empty(void) {
  return sb_queue_Isolette_Data_Model_On_Off_1_is_empty(&heat_control_recv_queue);
}

bool get_heat_control_poll(sb_event_counter_t *numDropped, Isolette_Data_Model_On_Off *data) {
  return sb_queue_Isolette_Data_Model_On_Off_1_dequeue((sb_queue_Isolette_Data_Model_On_Off_1_Recv_t *) &heat_control_recv_queue, numDropped, data);
}

bool get_heat_control(Isolette_Data_Model_On_Off *data) {
  sb_event_counter_t numDropped;
  return get_heat_control_poll (&numDropped, data);
}

uintmax_t get_heat_control_num_invalid(void) {
  return sb_queue_Isolette_Data_Model_On_Off_1_numInvalid((sb_queue_Isolette_Data_Model_On_Off_1_Recv_t *) &heat_control_recv_queue);
}

bool put_sv_heater_state(const Isolette_Data_Model_On_Off *data) {
  if (is_monitoring_enabled()) {
    sb_queue_Isolette_Data_Model_On_Off_1_enqueue((sb_queue_Isolette_Data_Model_On_Off_1_t *) sv_heater_state_queue_1, (Isolette_Data_Model_On_Off *) data);
  }

  return true;
}

volatile sb_queue_Isolette_Data_Model_On_Off_1_t *inj_sv_heater_state_queue;
sb_queue_Isolette_Data_Model_On_Off_1_Recv_t inj_sv_heater_state_recv;

bool get_inj_sv_heater_state(Isolette_Data_Model_On_Off *value) {
  if (inj_sv_heater_state_queue == NULL) {
    return false;
  }
  sb_event_counter_t numDropped;
  return sb_queue_Isolette_Data_Model_On_Off_1_dequeue(&inj_sv_heater_state_recv, &numDropped, value);
}

bool is_injection_enabled(void) {
  return inj_sv_heater_state_queue != NULL;
}

bool is_monitoring_enabled(void) {
  return sv_heater_state_queue_1 != NULL;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Isolette_Data_Model_On_Off_1_Recv_init(&heat_control_recv_queue, (sb_queue_Isolette_Data_Model_On_Off_1_t *) heat_control_queue_1);

  sb_queue_Isolette_Data_Model_On_Off_1_init((sb_queue_Isolette_Data_Model_On_Off_1_t *) sv_heater_state_queue_1);

  if (inj_sv_heater_state_queue != NULL) {
    sb_queue_Isolette_Data_Model_On_Off_1_Recv_init(&inj_sv_heater_state_recv, (sb_queue_Isolette_Data_Model_On_Off_1_t *) inj_sv_heater_state_queue);
  }

  heat_source_heat_source_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      if (inj_clr_requests != NULL) {
        if (inj_clr_requests[0] != inj_clr_applied[0]) {
          inj_clr_applied[0] = inj_clr_requests[0];
          __atomic_thread_fence(__ATOMIC_ACQUIRE);
          sb_event_counter_t cutoff = inj_clr_requests[1];
          // behind the cutoff: the difference taken as signed survives a wrap
          if ((intmax_t) (cutoff - heat_control_recv_queue.numRecv) > 0) {
            heat_control_recv_queue.numRecv = cutoff;
          }
        }
      }

      heat_source_heat_source_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      heat_source_heat_source_notify(channel);
  }
}
